def canJump(nums: List[int]) -> bool:
    reached = [False] * len(nums)
    reached[0] = True
    for i in range(len(nums)):
        if reached[i]:
            max_jump = nums[i]
            for j in range(1, max_jump + 1):
                if i + j < len(nums):
                    reached[i + j] = True
    return reached[-1]

