def generate(rng, n):
    if n <= 0:
        return [[1]]
    return [[rng.randint(0, min(n, 5)) for _ in range(n)]]

def generate_worst(rng, n):
    if n <= 0:
        return [[1]]
    arr = [2] * n
    arr[-1] = 0
    return [arr]

